// === Tab: mySketch ===
function getVel(x,y,v,tx,ty,g){
	let ax = tx-x;
	let ay = ty-y;
	let v2 = v*v;

	let dy = v2 - sqrt(v2*v2-g*(g*ax*ax+2*ay*v2));
	let dx = g*ax;
	return createVector(dx,dy).normalize().mult(v);
}


function getTheta(x,y,v,tx,ty,g){
	var ax = (tx-x);
	var ay = -(ty-y);
	var v2 = v*v;

	var dy = v2 - sqrt(  v2*v2 -  g*(g*ax*ax + 2*ay*v2)  );
	var dx = g*ax;
	return (Math.atan2(dy,dx));
}

let projectiles;
let grav = 0.03;

function preload() {
  font = loadFont("https://openprocessing.org/sketch/749423/files/Vogue.ttf");
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(220);
	projectiles=[];
	reset("l");
}


function fireAt(ax,ay,targetx,targety,vel,sync){
	let vec = getVel(ax,ay,vel,targetx,targety,grav);
	let ang = getTheta(ax,ay,vel,targetx,targety,grav);
	let vx = cos(ang)*vel;
	let vy = -sin(ang)*vel;
	let time = abs((ax-targetx)/vx);
	let m = new Projectile(ax,ay, vx,vy,sync-time,time);
	projectiles.push(m);
}
function reset(char){
	//
	let fontsize = width * 0.3;
	let options = {
    sampleFactor: 0.2,
    simplifyThreshold: 0
  };
	txt = char;
	let points = font.textToPoints(txt, width / 2 - fontsize / 3, height/2 + fontsize / 3, fontsize, options);
	let v = height*0.005;
  for (let p of points) {
		var ax = random(width/4,width*0.75);
		var ay = height*0.5+random(height*0.1);
		fireAt(ax,ay,p.x,p.y,v,300);

  }
}
function keyPressed() {
	reset(key);
}
function draw() {
	fill(222,10);
	rect(0,0,width,height);
	//ellipse((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 20, 20);
	let removeArr = [];
	for (let i = 0; i < projectiles.length; i++) {
    var m = projectiles[i];
    m.update();
    m.draw();
		if (m.pos.y>height) {
      removeArr.push(i);
    }

	}
	for(let j = removeArr.length-1; j > 0; j--){
     projectiles.splice(removeArr[j],1);
  }

}



class Projectile{
	constructor(x,y,vx,vy,del,time){
		this.pos = createVector(x, y);
		this.vel = createVector(vx, vy);
		this.delay=del;
		this.maxdelay=del;
		this.time=time;
	}
	update() {
		if(this.delay<=0){
			var iterations = 3;
			for(var i = 0;i<iterations;i++){

				this.pos.add(this.vel.x/iterations,this.vel.y/iterations);
				this.vel.add(0,grav/iterations);

			}
			this.time -= 1;
		}
		this.delay=this.delay-1;
	}
	draw(){
		let prog = 1- max(0,this.delay/this.maxdelay);
		fill(0,max(20,(2-abs(this.time) )*100  ));
		noStroke();
		ellipse(this.pos.x,this.pos.y,5*prog,5*prog);
		//line(this.pos.x,this.pos.y,this.pos.x+this.vel.x,this.pos.y+this.vel.y);
	}

}

